//! Drum sampler: a fixed 8-slot kit, each slot a one-shot WAV mapped to a MIDI
//! pitch. The samples are the synthetic kit generated by `examples/gen_drumkit.rs`
//! and embedded at compile time (`include_bytes!`), so the module ships its content
//! with no runtime file lookup.
//!
//! A real kit can replace the embedded one per instance: config key `kit` names
//! a directory (project-relative) holding WAVs by slot name (`kick.wav`,
//! `snare.wav`, `clap.wav`, `closed_hat.wav`, `open_hat.wav`, `low_tom.wav`,
//! `hi_tom.wav`, `crash.wav`). Missing or unreadable files keep their embedded
//! sound, so partial kits work.
//!
//! `configure`/`prepare` decode the WAVs (allocation off the audio thread);
//! `process` is RT-SAFE — it only reads the pre-decoded buffers and advances
//! playheads. A new hit on a slot retriggers it from the start; distinct slots
//! play at once.

use std::path::Path;

use crate::engine::node::{
    AudioNode, NodeIo, NoteKind, ParamCurve, ParamId, ParamSpec, Port, PortSpec, ProcessCtx,
    SignalKind,
};
use crate::engine::params::LinearRamp;
use crate::modules::wav;

const P_LEVEL: ParamId = 0;

const PARAMS: [ParamSpec; 1] = [ParamSpec {
    id: P_LEVEL,
    name: "level",
    unit: "dB",
    min: -60.0,
    max: 6.0,
    default: 0.0,
    curve: ParamCurve::Db,
}];

/// The kit: a MIDI pitch and its embedded WAV, in slot order. The pitches follow
/// the usual General-MIDI drum map closely enough to be familiar.
const KIT: [(u8, &[u8]); 8] = [
    (36, include_bytes!("../../assets/drumkit/kick.wav")),
    (38, include_bytes!("../../assets/drumkit/snare.wav")),
    (39, include_bytes!("../../assets/drumkit/clap.wav")),
    (42, include_bytes!("../../assets/drumkit/closed_hat.wav")),
    (46, include_bytes!("../../assets/drumkit/open_hat.wav")),
    (45, include_bytes!("../../assets/drumkit/low_tom.wav")),
    (50, include_bytes!("../../assets/drumkit/hi_tom.wav")),
    (49, include_bytes!("../../assets/drumkit/crash.wav")),
];

/// File names a `kit` config directory is probed for, in [`KIT`] slot order.
const SLOT_FILES: [&str; 8] = [
    "kick.wav",
    "snare.wav",
    "clap.wav",
    "closed_hat.wav",
    "open_hat.wav",
    "low_tom.wav",
    "hi_tom.wav",
    "crash.wav",
];

/// One kit slot: its trigger pitch, the decoded sample, and a single playhead.
struct Slot {
    pitch: u8,
    sample: Vec<f32>,
    bytes: &'static [u8],
    /// File-loaded replacement (`configure`), used over `bytes` when present.
    loaded: Option<(Vec<f32>, f32)>,
    /// Read position in the sample (fractional, for rate conversion).
    pos: f32,
    /// Samples to advance per output sample (`wav_sr / engine_sr`).
    step: f32,
    amp: f32,
    active: bool,
    /// Retrigger declick: the value the cut playback held, faded to zero and
    /// added to the fresh hit — a restart mid-ring would otherwise click.
    fade: f32,
    /// Attack micro-ramp (0..1): the generated samples can start hot
    /// (kick[0] ≈ 0.36), so each hit fades in over ~1 ms — pop-free, still
    /// punchy. Will also guard arbitrary user samples one day.
    att: f32,
}

impl Slot {
    fn new(pitch: u8, bytes: &'static [u8]) -> Self {
        Self {
            pitch,
            sample: Vec::new(),
            bytes,
            loaded: None,
            pos: 0.0,
            step: 1.0,
            amp: 0.0,
            active: false,
            fade: 0.0,
            att: 1.0,
        }
    }

    fn trigger(&mut self, vel: u8) {
        if self.active {
            // Carry the ringing sample's current value into the declick fade
            // (accumulating if a fade is already running) instead of cutting.
            self.fade += sample_at(&self.sample, self.pos) * self.amp;
        }
        self.pos = 0.0;
        self.amp = vel as f32 / 127.0;
        self.att = 0.0;
        self.active = !self.sample.is_empty();
    }

    /// `fade_step`/`att_step` are the per-sample declick decrement and attack
    /// increment (set from the sample rate by the module). // RT-SAFE
    fn render(&mut self, fade_step: f32, att_step: f32) -> f32 {
        let mut out = self.fade;
        if self.fade > 0.0 {
            self.fade = (self.fade - fade_step).max(0.0);
        } else if self.fade < 0.0 {
            self.fade = (self.fade + fade_step).min(0.0);
        }
        if !self.active {
            return out;
        }
        out += sample_at(&self.sample, self.pos) * self.amp * self.att;
        self.att = (self.att + att_step).min(1.0);
        self.pos += self.step;
        if self.pos >= (self.sample.len() as f32) - 1.0 {
            self.active = false;
        }
        out
    }
}

/// Retrigger declick length (seconds): full scale fades out in this time.
const FADE_S: f32 = 0.003;
/// Attack micro-ramp length (seconds): kills the sample-start pop.
const ATTACK_S: f32 = 0.001;

pub struct DrumSampler {
    slots: [Slot; 8],
    level: LinearRamp,
    /// Per-sample declick decrement (`1 / (FADE_S · sr)`).
    fade_step: f32,
    /// Per-sample attack increment (`1 / (ATTACK_S · sr)`).
    att_step: f32,
}

impl Default for DrumSampler {
    fn default() -> Self {
        Self {
            slots: std::array::from_fn(|i| Slot::new(KIT[i].0, KIT[i].1)),
            level: LinearRamp::new(1.0, 10.0, 48_000.0),
            fade_step: 1.0 / (FADE_S * 48_000.0),
            att_step: 1.0 / (ATTACK_S * 48_000.0),
        }
    }
}

impl DrumSampler {
    fn trigger(&mut self, pitch: u8, vel: u8) {
        for slot in &mut self.slots {
            if slot.pitch == pitch {
                slot.trigger(vel);
            }
        }
    }
}

impl AudioNode for DrumSampler {
    fn process(&mut self, _ctx: &ProcessCtx, io: &mut NodeIo) {
        for ev in io.notes() {
            // Drums are one-shots: only note-ons fire a hit, note-offs are ignored.
            if let NoteKind::On { pitch, vel } = ev.kind {
                self.trigger(pitch, vel);
            }
        }

        let out = io.output(0);
        for slot in out.iter_mut() {
            let level = self.level.tick();
            let mut sum = 0.0;
            for s in &mut self.slots {
                sum += s.render(self.fade_step, self.att_step);
            }
            *slot = sum * level;
        }
        io.spread_output(0);
    }

    fn ports(&self) -> PortSpec {
        PortSpec {
            inputs: vec![Port {
                name: "notes",
                kind: SignalKind::Notes,
            }],
            outputs: vec![Port {
                name: "out",
                kind: SignalKind::Audio,
            }],
        }
    }

    fn params(&self) -> &[ParamSpec] {
        &PARAMS
    }

    fn set_param(&mut self, id: ParamId, value: f32) {
        if id == P_LEVEL {
            self.level.set_target(PARAMS[0].denormalize(value));
        }
    }

    fn configure(&mut self, config: &[(String, String)], base_dir: &Path) {
        for (key, value) in config {
            if key == "kit" {
                let dir = wav::resolve(base_dir, value);
                for (slot, file) in self.slots.iter_mut().zip(SLOT_FILES) {
                    slot.loaded = wav::load_mono(&dir.join(file));
                }
            }
        }
    }

    fn prepare(&mut self, sample_rate: f32, _max_block: usize) {
        for slot in &mut self.slots {
            let (sample, wav_sr) = slot
                .loaded
                .clone()
                .or_else(|| wav::decode_mono_bytes(slot.bytes))
                .unwrap_or((Vec::new(), sample_rate));
            slot.step = wav_sr / sample_rate;
            slot.sample = sample;
            slot.pos = 0.0;
            slot.active = false;
            slot.fade = 0.0;
            slot.att = 1.0;
        }
        self.fade_step = 1.0 / (FADE_S * sample_rate);
        self.att_step = 1.0 / (ATTACK_S * sample_rate);
        self.level = LinearRamp::new(default_real(P_LEVEL), 10.0, sample_rate);
    }
}

/// Read a sample at a fractional position with linear interpolation. // RT-SAFE
fn sample_at(buf: &[f32], pos: f32) -> f32 {
    let i = pos as usize;
    if i + 1 >= buf.len() {
        return 0.0;
    }
    let frac = pos - i as f32;
    buf[i] * (1.0 - frac) + buf[i + 1] * frac
}

/// Real default value for a parameter (round-trips through the curve).
fn default_real(id: ParamId) -> f32 {
    let spec = &PARAMS[id as usize];
    spec.denormalize(spec.normalize(spec.default))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::engine::node::NoteEvent;

    fn kit() -> DrumSampler {
        let mut s = DrumSampler::default();
        s.prepare(48_000.0, 256);
        s
    }

    fn render(s: &mut DrumSampler, notes: &[NoteEvent], frames: usize, out: &mut Vec<f32>) {
        out.resize(frames, 0.0);
        let ctx = ProcessCtx {
            sample_rate: 48_000.0,
            frames,
            channels: 1,
            samples_per_beat: 0.0,
            beat_phase: 0.0,
        };
        let mut io = NodeIo::new(notes, &[], out, frames, 1);
        s.process(&ctx, &mut io);
    }

    fn peak(buf: &[f32]) -> f32 {
        buf.iter().fold(0.0f32, |m, &s| m.max(s.abs()))
    }

    fn hit(pitch: u8, vel: u8) -> NoteEvent {
        NoteEvent {
            frame: 0,
            kind: NoteKind::On { pitch, vel },
        }
    }

    #[test]
    fn struck_slot_is_audible_and_clean() {
        let mut s = kit();
        let mut buf = Vec::new();
        render(&mut s, &[hit(36, 110)], 8192, &mut buf); // kick
        let p = peak(&buf);
        assert!(p > 0.05, "kick is inaudible, peak {p}");
        assert!(p <= 1.0, "kick clips, peak {p}");
        assert!(buf.iter().all(|s| s.is_finite()), "produced NaN/inf");
    }

    #[test]
    fn unmapped_pitch_is_silent() {
        let mut s = kit();
        let mut buf = Vec::new();
        render(&mut s, &[hit(60, 110)], 4096, &mut buf); // no slot at pitch 60
        assert!(peak(&buf) < 1.0e-6, "unmapped pitch made sound");
    }

    #[test]
    fn retrigger_mid_ring_is_click_free() {
        // Regression (found by the MVP recette probe on the demo song): a hit
        // on a still-ringing slot restarted the playhead cold, jumping from
        // the current sample value to ~0 — an audible click on open hat and
        // crash. The cut value now fades out over FADE_S instead.
        use crate::analysis::levels;
        let mut s = kit();
        let mut whole = Vec::new();
        let mut buf = Vec::new();
        render(&mut s, &[hit(49, 110)], 4800, &mut buf); // crash, long ring
        whole.extend_from_slice(&buf);
        render(&mut s, &[hit(49, 90)], 9600, &mut buf); // retrigger mid-ring
        whole.extend_from_slice(&buf);
        assert!(whole.iter().all(|x| x.is_finite()));
        let clicks = levels::detect_clicks(&whole, 48_000);
        assert!(clicks.is_empty(), "retrigger clicked: {clicks:?}");
    }

    #[test]
    fn one_shot_frees_itself() {
        // The kick is ~0.35 s; well past that it must fall silent on its own.
        let mut s = kit();
        let mut buf = Vec::new();
        render(&mut s, &[hit(36, 110)], 48_000, &mut buf); // 1 s, past the sample
        let tail = peak(&buf[40_000..]);
        assert!(tail < 1.0e-4, "one-shot did not free itself, tail {tail}");
    }

    #[test]
    fn kit_config_swaps_a_slot_and_spares_the_rest() {
        let dir = std::env::temp_dir().join(format!("telenn_kit_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        // A kick nothing like the embedded one: 50 ms of constant 0.5.
        let spec = hound::WavSpec {
            channels: 1,
            sample_rate: 48_000,
            bits_per_sample: 16,
            sample_format: hound::SampleFormat::Int,
        };
        let mut w = hound::WavWriter::create(dir.join("kick.wav"), spec).unwrap();
        for _ in 0..2400 {
            w.write_sample((0.5 * i16::MAX as f32) as i16).unwrap();
        }
        w.finalize().unwrap();

        let mut s = DrumSampler::default();
        let config = vec![("kit".to_string(), dir.to_string_lossy().into_owned())];
        s.configure(&config, std::path::Path::new(""));
        s.prepare(48_000.0, 256);
        std::fs::remove_dir_all(&dir).ok();

        let mut buf = Vec::new();
        render(&mut s, &[hit(36, 127)], 2048, &mut buf);
        // Well after the 1 ms attack ramp the loaded plateau reads back.
        let mid = buf[1000];
        assert!((mid - 0.5).abs() < 0.02, "loaded kick not playing: {mid}");
        // The snare file was absent: its embedded sample still fires.
        let mut buf2 = Vec::new();
        render(&mut s, &[hit(38, 110)], 8192, &mut buf2);
        assert!(peak(&buf2) > 0.05, "embedded fallback lost");
    }

    #[test]
    fn velocity_scales_amplitude() {
        let mut soft = kit();
        let mut hard = kit();
        let (mut a, mut b) = (Vec::new(), Vec::new());
        render(&mut soft, &[hit(38, 30)], 8192, &mut a);
        render(&mut hard, &[hit(38, 120)], 8192, &mut b);
        assert!(
            peak(&b) > peak(&a) * 2.0,
            "velocity did not scale: {} vs {}",
            peak(&a),
            peak(&b)
        );
    }
}
